* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: #333;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 30px;
  color: white;
}

.header h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.header p {
  font-size: 1.2rem;
  opacity: 0.9;
}

.game-container {
  background: white;
  border-radius: 20px;
  padding: 30px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.1);
  width: 100%;
  max-width: 500px;
}

/* Asset Selector */
.asset-selector {
  display: flex;
  gap: 10px;
  margin-bottom: 30px;
  justify-content: center;
}

.asset-btn {
  padding: 12px 20px;
  border: 2px solid #e1e5e9;
  border-radius: 10px;
  background: white;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.9rem;
}

.asset-btn:hover {
  border-color: #667eea;
  transform: translateY(-1px);
}

.asset-btn.active {
  background: #667eea;
  color: white;
  border-color: #667eea;
}

.asset-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* Price Display */
.price-display {
  text-align: center;
  margin-bottom: 30px;
}

.price-display h2 {
  font-size: 1.5rem;
  color: #333;
  margin-bottom: 10px;
}

.current-price {
  font-size: 3rem;
  font-weight: bold;
  color: #333;
  margin-bottom: 5px;
  font-family: 'Courier New', monospace;
}

.price-info {
  color: #666;
  font-size: 0.9rem;
}

/* Score */
.score {
  display: flex;
  justify-content: center;
  gap: 30px;
  margin-bottom: 30px;
  padding: 20px;
  background: #f8f9fa;
  border-radius: 15px;
}

.score-item {
  text-align: center;
}

.score-number {
  display: block;
  font-size: 2rem;
  font-weight: bold;
  line-height: 1;
}

.score-label {
  display: block;
  font-size: 0.8rem;
  color: #666;
  margin-top: 5px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.wins .score-number {
  color: #28a745;
}

.losses .score-number {
  color: #dc3545;
}

.accuracy .score-number {
  color: #667eea;
}

/* Game Area */
.game-area {
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

/* Prediction Buttons */
.prediction-buttons {
  display: flex;
  gap: 20px;
}

.predict-btn {
  padding: 20px 30px;
  border: none;
  border-radius: 15px;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.2s;
  min-width: 150px;
}

.predict-btn.up {
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
}

.predict-btn.down {
  background: linear-gradient(135deg, #dc3545, #fd7e14);
  color: white;
}

.predict-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.2);
}

.predict-btn:active {
  transform: translateY(0);
}

/* Prediction Active */
.prediction-active {
  text-align: center;
  width: 100%;
}

.prediction-active h3 {
  color: #667eea;
  margin-bottom: 20px;
  font-size: 1.5rem;
