{"path": "price-predictor/src/App.jsx", "content": "import { useState, useEffect, useCallback } from 'react'
import './App.css'

// Pyth feed IDs for popular crypto assets
const ASSETS = {
  'BTC/USD': '0xe62df6c8b4a85fe1a67db44dc12de5db330f7ac66b72dc658afedf0f4a415b43',
  'ETH/USD': '0xff61491a931112ddf1bd8147cd1b641375f79f5825126d665480874634fd0ace',
  'SOL/USD': '0xef0d8b6fda2ceba41da15d4095d1da392a0d2f8ed0c6c7bc0f4cfac8c280b56d'
}

const PREDICTION_DURATION = 60 // seconds

function App() {
  const [selectedAsset, setSelectedAsset] = useState('BTC/USD')
  const [currentPrice, setCurrentPrice] = useState(null)
  const [previousPrice, setPreviousPrice] = useState(null)
  const [prediction, setPrediction] = useState(null) // 'up' or 'down'
  const [predictionStartTime, setPredictionStartTime] = useState(null)
  const [predictionStartPrice, setPredictionStartPrice] = useState(null)
  const [timeRemaining, setTimeRemaining] = useState(0)
  const [score, setScore] = useState({ wins: 0, losses: 0 })
  const [gameStatus, setGameStatus] = useState('waiting') // 'waiting', 'predicting', 'completed'
  const [lastResult, setLastResult] = useState(null)
  const [loading, setLoading] = useState(false)

  // Fetch price from Pyth Hermes API
  const fetchPrice = useCallback(async () => {
    try {
      const feedId = ASSETS[selectedAsset]
      const response = await fetch(`https://hermes.pyth.network/v2/updates/price/latest?ids[]=${feedId}`)
      const data = await response.json()

      if (data.parsed && data.parsed.length > 0) {
        const priceData = data.parsed[0].price
        const price = parseFloat(priceData.price) * Math.pow(10, priceData.expo)

        setPreviousPrice(currentPrice)
        setCurrentPrice(price)
        return price
      }
    } catch (error) {
      console.error('Failed to fetch price:', error)
    }
    return null
  }, [selectedAsset, currentPrice])

  // Start a new prediction
  const startPrediction = (direction) => {
    if (gameStatus !== 'waiting' || !currentPrice) return

    setPrediction(direction)
    setPredictionStartTime(Date.now())
    setPredictionStartPrice(currentPrice)
    setTimeRemaining(PREDICTION_DURATION)
    setGameStatus('predicting')
    setLastResult(null)
  }

  // Complete the prediction and check result
  const completePrediction = useCallback(async () => {
    if (gameStatus !== 'predicting') return

    setLoading(true)
    const finalPrice = await fetchPrice()

    if (finalPrice && predictionStartPrice) {
      const priceChange = finalPrice - predictionStartPrice
      const actualDirection = priceChange > 0 ? 'up' : 'down'
      const won = prediction === actualDirection

      setScore(prev => ({
        wins: won ? prev.wins + 1 : prev.wins,
        losses: won ? prev.losses : prev.losses + 1
      }))

      setLastResult({
        won,
        prediction,
        actualDirection,
        startPrice: predictionStartPrice,
        endPrice: finalPrice,
        change: priceChange,
        changePercent: ((priceChange / predictionStartPrice) * 100).toFixed(4)
      })
    }

    setGameStatus('completed')
    setLoading(false)
  }, [gameStatus, fetchPrice, predictionStartPrice, prediction])

  // Reset for new prediction
  const resetPrediction = () => {
    setPrediction(null)
    setPredictionStartTime(null)
    setPredictionStartPrice(null)
    setTimeRemaining(0)
    setGameStatus('waiting')
    setLastResult(null)
  }

  // Handle countdown timer
  useEffect(() => {
    if (gameStatus === 'predicting' && timeRemaining > 0) {
      const timer = setTimeout(() => {
        setTimeRemaining(prev => prev - 1)
      }, 1000)
      return () => clearTimeout(timer)
    } else if (gameStatus === 'predicting' && timeRemaining === 0) {
      completePrediction()
    }
  }, [gameStatus, timeRemaining, completePrediction])

  // Fetch prices regularly
  useEffect(() => {
    fetchPrice()
    const interval = setInterval(fetchPrice, 2000) // Update every 2 seconds
    return () => clearInterval(interval)
  }, [fetchPrice])

  // Reset when asset changes
  useEffect(() => {
    resetPrediction()
  }, [selectedAsset])

  const formatPrice = (price) => {
    if (!price) return '---'
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: selectedAsset === 'BTC/USD' ? 2 : 4
    }).format(price)
  }

  const getPriceChangeIndicator = () => {
    if (!currentPrice || !previousPrice) return ''
    return currentPrice > previousPrice ? '📈' : currentPrice < previousPrice ? '📉' : '➡️'
  }

  return (
    <div className="app">
      <header className="header">
        <h1>🎯 Crypto Price Predictor</h1>
        <p>Predict if the price will go UP or DOWN in {PREDICTION_DURATION} seconds!</p>
      </header>

      <div className="game-container">
        {/* Asset Selector */}
        <div className="asset-selector">
          {Object.keys(ASSETS).map(asset => (
            <button
              key={asset}
              className={`asset-btn ${selectedAsset === asset ? 'active' : ''}`}
              onClick={() => setSelectedAsset(asset)}
              disabled={gameStatus === 'predicting'}
            >
              {asset}
            </button>
          ))}
        </div>

        {/* Current Price Display */}
        <div className="price-display">
          <h2>{selectedAsset}</h2>
          <div className="current-price">
            {formatPrice(currentPrice)} {getPriceChangeIndicator()}
          </div>
          {currentPrice && (
            <div className="price-info">
              Live price via Pyth Network
            </div>
          )}
        </div>

        {/* Score */}
        <div className="score">
          <div className="score-item wins">
            <span className="score-number">{score.wins}</span>
            <span className="score-label">Wins</span>
          </div>
          <div className="score-item losses">
            <span className="score-number">{score.losses}</span>
            <span className="score-label">Losses</span>
          </div>
          <div className="score-item accuracy">
            <span className="score-number">
              {score.wins + score.losses > 0 
                ? Math.round((score.wins / (score.wins + score.losses)) * 100)
                : 0}%
            </span>
            <span className="score-label">Accuracy</span>
          </div>
        </div>

        {/* Game Area */}
        <div className="game-area">
          {gameStatus === 'waiting' && currentPrice && (
            <div className="prediction-buttons">
              <button
                className="predict-btn up"
                onClick={() => startPrediction('up')}
              >
                📈 Predict UP
              </button>
              <button
                className="predict-btn down"
                onClick={() => startPrediction('down')}
              >
                📉 Predict DOWN
              </button>
            </div>
          )}

          {gameStatus === 'predicting' && (
            <div className="prediction-active">
              <h3>🎯 Prediction Active</h3>
              <div className="prediction-info">
                <p>You predicted: <strong>{prediction.toUpperCase()}</strong></p>
                <p>Starting price: <strong>{formatPrice(predictionStartPrice)}</strong></p>
                <p>Current price: <strong>{formatPrice(currentPrice)}</strong></p>
              </div>
              <div className="countdown">
                <div className="countdown-number">{timeRemaining}</div>
                <div className="countdown-label">seconds remaining</div>
              </div>
            </div>
          )}

          {gameStatus === 'completed' && (
            <div className="prediction-result">
              {loading ? (
                <div className="loading">Checking final price...</div>
              ) : lastResult ? (
                <div className={`result ${lastResult.won ? 'win' : 'loss'}`}>
                  <h3>{lastResult.won ? '🎉 You Won!' : '😔 You Lost!'}</h3>
                  <div className="result-details">
                    <p>Your prediction: <strong>{lastResult.prediction.toUpperCase()}</strong></p>
                    <p>Actual direction: <strong>{lastResult.actualDirection.toUpperCase()}</strong></p>
                    <p>Price change: <strong>
                      {lastResult.change > 0 ? '+' : ''}{formatPrice(Math.abs(lastResult.change))} 
                      ({lastResult.change > 0 ? '+' : ''}{lastResult.changePercent}%)
                    </strong></p>
                    <p>
                      {formatPrice(lastResult.startPrice)} → {formatPrice(lastResult.endPrice)}
                    </p>
                  </div>
                  <button className="play-again-btn" onClick={resetPrediction}>
                    Play Again
                  </button>
                </div>
              ) : (
                <div className="error">
                  <p>Failed to get final price. Please try again.</p>
                  <button className="play-again-btn" onClick={resetPrediction}>
                    Try Again
                  </button>
                </div>
              )}
            </div>
          )}

          {!currentPrice && (
            <div className="loading">Loading price data...</div>
          )}
        </div>
      </div>

      <footer className="footer">
        <p>Powered by <a href="https://pyth.network" target="_blank" rel="noopener noreferrer">Pyth Network</a></p>
      </footer>
    </div>
  )
}

export default App"}

